def _expect(tokens, expected_type):
    if not tokens or tokens[0].type != expected_type:
        raise SQLSyntaxError(f"Expected {expected_type}, got {tokens[0].type if tokens else 'EOF'}")
    return tokens.pop(0)

def _parse_primary(tokens):
    token = tokens[0]
    if token.type == TokenType.INTEGER:
        return Literal(int(_expect(tokens, TokenType.INTEGER).value))
    elif token.type == TokenType.STRING:
        return Literal(_expect(tokens, TokenType.STRING).value)
    elif token.value.upper() == "TRUE":
        _expect(tokens, TokenType.KEYWORD)
        return Literal(True)
    elif token.value.upper() == "FALSE":
        _expect(tokens, TokenType.KEYWORD)
        return Literal(False)
    elif token.value.upper() == "NULL":
        _expect(tokens, TokenType.KEYWORD)
        return Literal(None)
    elif token.type == TokenType.IDENTIFIER:
        return ColumnRef(_expect(tokens, TokenType.IDENTIFIER).value)
    elif token.type == TokenType.OPERATOR and token.value == '(':
        _expect(tokens, TokenType.OPERATOR)
        expr = parse_expression(tokens)
        _expect(tokens, TokenType.OPERATOR)
        return expr
    else:
        raise SQLSyntaxError(f"Unexpected token: {token}")

def _parse_predicate(tokens):
    primary = _parse_primary(tokens)
    if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value in COMPARISON_OPS:
        op = _expect(tokens, TokenType.OPERATOR).value
        right = _parse_primary(tokens)
        return Comparison(op, primary, right)
    elif tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value.upper() == "IS":
        _expect(tokens, TokenType.KEYWORD)
        if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value.upper() == "NOT":
            _expect(tokens, TokenType.KEYWORD)
            _expect(tokens, TokenType.KEYWORD)
            return IsNull(primary, True)
        else:
            _expect(tokens, TokenType.KEYWORD)
            return IsNull(primary, False)
    else:
        return primary

def _parse_not_expr(tokens):
    if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value.upper() == "NOT":
        _expect(tokens, TokenType.KEYWORD)
        return Not(_parse_not_expr(tokens))
    else:
        return _parse_predicate(tokens)

def _parse_and_expr(tokens):
    expr = _parse_not_expr(tokens)
    while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value.upper() == "AND":
        _expect(tokens, TokenType.KEYWORD)
        expr = And(expr, _parse_not_expr(tokens))
    return expr

def _parse_or_expr(tokens):
    expr = _parse_and_expr(tokens)
    while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value.upper() == "OR":
        _expect(tokens, TokenType.KEYWORD)
        expr = Or(expr, _parse_and_expr(tokens))
    return expr

def parse_expression(tokens: list[Token]) -> Expr:
    expr = _parse_or_expr(tokens)
    if tokens and tokens[0].type != TokenType.EOF:
        raise SQLSyntaxError("Trailing tokens in expression")
    _expect(tokens, TokenType.EOF)
    return expr

def _parse_column_def(tokens):
    name = _expect(tokens, TokenType.IDENTIFIER).value
    _expect(tokens, TokenType.KEYWORD)
    type_str = tokens[0].value.upper()
    if type_str == "INTEGER":
